-- V1：配置版本快照（H2 方言）
--
-- 消费方是 ADR-0010 第 6 节「配置版本与回滚」：每次配置变更产生一个不可变快照，
-- 带版本号。它回答两个问题 —— 现在生效的是哪一版、能回滚到哪一版。
-- 多副本之间广播的是「变更事件 + 版本号」，不是全量配置，所以正文留在库里就够了。
--
-- 表由消费方倒推，不由 legacy 的 20 张表倒推（ADR-0017 第 4 节）：
-- 其余几张表（规则 / 命中统计 / 厂商声明 / 调用历史 / 脱敏规则 / API Key）
-- 等各自的消费方落地再建，不为「以后可能用到」先铺空表。
--
-- 方言差异只有一处：正文的类型。H2 用 CLOB，PostgreSQL 目录里的同名文件用 TEXT ——
-- 迁移按方言分目录正是为了容纳这种差异，而不是在一份 SQL 里写 if。
-- 主键两边都写 `generated by default as identity`：H2 2.x 与 PG 10+ 都认这个写法，
-- 通用 SQL 优先（ADR-0017 第 2 节纪律 8）。
--
-- 已发布的迁移不可再改（Flyway 按校验和判定）：schema 变更一律新增 V2__ 增量脚本。
create table config_snapshot (
    id bigint generated by default as identity primary key,
    version bigint not null,
    content clob not null,
    created_at timestamp(6) not null,
    actor varchar(64) not null,
    constraint uq_config_snapshot_version unique (version)
);
